(()=>{let t=self;t.addEventListener("push",i=>{let n=i.data?JSON.parse(i.data.text()):{},e=n.title||"Baby App",o=n.body||"新しい通知があります。",a=n.url||"/";i.waitUntil(t.registration.showNotification(e,{body:o,icon:"/icons/icon-192x192.png",badge:"/favicon.ico",data:{url:a}}))}),t.addEventListener("notificationclick",i=>{i.notification.close();let n=i.notification.data.url;i.waitUntil(t.clients.matchAll({type:"window"}).then(i=>{for(let t of i)if(t.url===n&&"focus"in t)return t.focus();if(t.clients.openWindow)return t.clients.openWindow(n)}))})})();